use collections::HashMap;

use crate::{KeybindingKeystroke, Keystroke};

/// Characters generated by one physical USB HID keyboard position on the host.
#[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct KeyboardCharacterKey {
    /// Usage on the USB keyboard page.
    pub usage: u16,
    /// Base, Shift, Option, Shift-Option, Command and Shift-Command output.
    pub layers: [String; 6],
    /// Caps Lock output for base, Shift, Option and Shift-Option, when available.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub caps_lock_layers: Option<[String; 4]>,
}

/// A trait for platform-specific keyboard layouts
pub trait PlatformKeyboardLayout {
    /// Get the keyboard layout ID, which should be unique to the layout
    fn id(&self) -> &str;
    /// Get the keyboard layout display name
    fn name(&self) -> &str;
    /// Samples printable key positions for an independently hosted application.
    fn character_keys(&self) -> Vec<KeyboardCharacterKey> {
        Vec::new()
    }
}

/// A trait for platform-specific keyboard mappings
pub trait PlatformKeyboardMapper {
    /// Map a key equivalent to its platform-specific representation
    fn map_key_equivalent(
        &self,
        keystroke: Keystroke,
        use_key_equivalents: bool,
    ) -> KeybindingKeystroke;
    /// Get the key equivalents for the current keyboard layout,
    /// only used on macOS
    fn get_key_equivalents(&self) -> Option<&HashMap<char, char>>;
}

/// A dummy implementation of the platform keyboard mapper
pub struct DummyKeyboardMapper;

impl PlatformKeyboardMapper for DummyKeyboardMapper {
    fn map_key_equivalent(
        &self,
        keystroke: Keystroke,
        _use_key_equivalents: bool,
    ) -> KeybindingKeystroke {
        KeybindingKeystroke::from_keystroke(keystroke)
    }

    fn get_key_equivalents(&self) -> Option<&HashMap<char, char>> {
        None
    }
}
